sed -i 's/        let l0 = d1.dot(&d1.t());/        let num_vertices = d1.shape()[0];\n        let num_edges = d1.shape()[1];\n        let mut l0 = Array2::<f32>::zeros((num_vertices, num_vertices));\n        for e in 0..num_edges {\n            let mut v1 = usize::MAX;\n            let mut v2 = usize::MAX;\n            for v in 0..num_vertices {\n                if d1[[v, e]] > 0.0 { v1 = v; }\n                else if d1[[v, e]] < 0.0 { v2 = v; }\n            }\n            if v1 != usize::MAX \&\& v2 != usize::MAX {\n                l0[[v1, v1]] += 1.0;\n                l0[[v2, v2]] += 1.0;\n                l0[[v1, v2]] -= 1.0;\n                l0[[v2, v1]] -= 1.0;\n            }\n        }/' src/quantum_topology.rs
